-- Bounty board settings (bounty.lua, bounty_core.lua). Loaded with
--     Chaos.bountyConfig = dofile("data/scripts/chaos/bounty_config.lua")
-- The monster pool the contracts are picked from is bounty_pool.lua (generated by tools/gen_bounty_pool.py).
-- Lua 5.1 / LuaJIT compatible. Item ids are SERVER ids.

return {
	-- the board rolls every day at this server-local hour (the "bounty day" runs from rollHour to rollHour)
	rollHour = 6,
	maxActive = 3, -- contracts a player may hold at once (accepted and not finished)
	visibleAround = 1, -- a player sees the band of their level plus this many bands below and above it
	partyRange = 30, -- party members within this many tiles (same floor) of the killer get the kill too
	table = "chaos_bounty", -- server/sql/chaos.sql
	-- multi-client characters (Chaos.isMultiClient) may take contracts and hunt; a contract that got a kill while the
	-- character was multi-clienting pays nothing when mcReward is false (as the world boss event treats them)
	mcReward = false,
	progressNotices = {25, 50, 75}, -- percent: a status message (50 also a toast in the notification module)

	-- contract slots of every band, in order. "boss" falls back to "hunt" when no boss fits the band.
	slots = {"hunt", "hunt", "elite", "boss"},
	-- elite: kill N monsters of the type that are at least this tier (monster_tiers.lua). Weights pick the tier.
	elite = {
		{tier = "magic", weight = 70, count = {4, 6}},
		{tier = "rare", weight = 30, count = {1, 2}}
	},
	eliteMinSpawns = 20, -- elite targets must have this many spawn entries (tiers are rare: ~8% of spawns)
	bossCount = {1, 1},
	fewSpawns = 20, -- hunt targets with fewer spawn entries than this get fewer kills (x fewSpawnsMult)
	fewSpawnsMult = 0.6,

	-- reward multiplier per contract type (gold and Orbs of Upheaval; Orbs of Fate are rounded up)
	typeMult = {hunt = 1.0, elite = 1.5, boss = 1.5},
	-- experience (2026-10-22, "as bounties dão muito pouca xp": 3-4% of one level was 87 exp at level 8, less than one
	-- kill gives with the stage). expShare percent of the base experience the contract's kills give the player: the
	-- monster's experience x its pace curve x the experience stage of the player's level (bounty_core.lua B.expReward),
	-- for an elite also the kills of the type made while looking for the tier (eliteSearch). At least expFloor and at
	-- most expCap percent of the experience from level L to L + 1, L = min(player level, band max level). The board
	-- shows the exact amount for the player's level; it is paid without any bonus (Player:addExperience).
	expShare = {hunt = 40, elite = 40, boss = 100},
	expFloor = {hunt = 10, elite = 15, boss = 50},
	expCap = {hunt = 2000, elite = 2000, boss = 2000},
	-- experience multiplier of the elite tiers (bounty.lua takes them from monster_tiers.lua ChaosTiers[tier].xp)
	tierXp = {magic = 2, rare = 4},
	-- kills of the type, about, per counted elite kill (monster_tiers.lua spawnChance: magic or better 7.75% of spawns,
	-- rare or better 1.75%; ambushes add some)
	eliteSearch = {magic = 12, rare = 50},

	-- level bands. pick = level window of the monsters the contracts use (bounty_pool.lua "level").
	-- reward: gold goes to the bank, orbs to the backpack (inbox when it is full).
	bands = {
		{min = 8, max = 49, pick = {5, 49}, kills = {60, 120},
			reward = {gold = 10000, chaos = 1, divine = 0}, weekly = {chaos = 5, divine = 1}},
		{min = 50, max = 149, pick = {40, 149}, kills = {100, 180},
			reward = {gold = 50000, chaos = 2, divine = 0}, weekly = {chaos = 6, divine = 1}},
		{min = 150, max = 299, pick = {120, 299}, kills = {120, 200},
			reward = {gold = 150000, chaos = 3, divine = 0}, weekly = {chaos = 8, divine = 2}},
		{min = 300, max = 499, pick = {250, 499}, kills = {120, 200},
			reward = {gold = 400000, chaos = 4, divine = 0}, weekly = {chaos = 10, divine = 2}},
		{min = 500, max = 799, pick = {420, 799}, kills = {100, 180},
			reward = {gold = 1000000, chaos = 5, divine = 1}, weekly = {chaos = 12, divine = 3}},
		{min = 800, max = 999999, pick = {640, 1500}, kills = {80, 150},
			reward = {gold = 2000000, chaos = 6, divine = 2}, weekly = {chaos = 15, divine = 4}}
	},

	-- weekly bonus: completing this many contracts in one bounty week (Monday rollHour to Monday rollHour) gives a
	-- chest (a present box renamed) with the band's "weekly" orbs inside. 4 (was 7, 2026-10-15, respect the players'
	-- time): about two short sessions a week earn it; a contract is 60-200 kills, about 15-25 minutes
	weeklyNeed = 4,
	weeklyChestId = 1990,
	weeklyChestName = "bounty chest",
	-- crafting orbs added to every weekly chest (data/lib/chaos_crafting.lua); {} for none
	weeklyExtra = {{id = 29851, count = 3, name = "Orbs of Awakening"}, {id = 24697, count = 1, name = "Orb of Unmaking"},
		{id = 32256, count = 5, name = "Whetstones"}, {id = 32251, count = 2, name = "Orbs of Tempering"}},

	items = {chaos = 29856, divine = 29857},

	-- rerolls (2026-10-15): charges bought in the Candlemarks shop (ChaosBounty.addRerolls); one gives an accepted contract
	-- another monster of its band and type. Player storage (lent from the catchup block 7102400-7102409, server/README.md
	-- "Storage keys")
	rerollStorage = 7102403
}
